  const rows = getDb()
    .select({ projectId: projectMutes.projectId })
    .from(projectMutes)
    .where(
      and(orgPredicate(projectMutes.orgId, orgId), eq(projectMutes.userId, userId)),
    )
    .all();
  return rows.map((row) => brandId<ProjectId>(row.projectId));
}

export async function addMute(
  orgId: OrgId,
  userId: UserId,
  projectId: ProjectId,
): Promise<void> {
  getDb()
    .insert(projectMutes)
    .values({ orgId, userId, projectId, mutedAt: toIsoTimestamp(new Date()) })
    .onConflictDoNothing()
    .run();
}

export async function removeMute(
  orgId: OrgId,
  userId: UserId,
  projectId: ProjectId,
): Promise<void> {
  getDb()
    .delete(projectMutes)
    .where(
      and(
        orgPredicate(projectMutes.orgId, orgId),
        eq(projectMutes.userId, userId),
        eq(projectMutes.projectId, projectId),
      ),
    )
    .run();
}
